SELECT molecule_dictionary.chembl_id, molecule_dictionary.pref_name, compound_structures.canonical_smiles, drug_indication.efo_id AS indication_curie, drug_indication.mesh_heading AS indication_label, drug_indication.max_phase_for_ind FROM molecule_dictionary JOIN drug_indication ON molecule_dictionary.molregno = drug_indication.molregno JOIN compound_structures ON molecule_dictionary.molregno = compound_structures.molregno WHERE drug_indication.max_phase_for_ind = 4 AND drug_indication.mesh_heading = 'breast cancer' ORDER BY molecule_dictionary.chembl_id, molecule_dictionary.pref_name, compound_structures.canonical_smiles, drug_indication.efo_id, drug_indication.mesh_heading, drug_indication.max_phase_for_ind
